package main

import (
	"bytes"
	"flag"
	"fmt"
	"go/format"
	"os"
	"path/filepath"
	"strings"

	"golang.org/x/tools/go/packages"
)

// otelwrapgen generates lightweight OpenTelemetry span wrappers for selected interfaces.
//
// Design goals:
// - Zero call-site changes: wrappers are hooked in at providers (InitService/NewXRepo).
// - Low code intrusion: only adds spans around interface methods.
// - No reflection or runtime proxies (Go cannot do this safely); codegen instead.
//
// Generated file name is stable so it can be overwritten safely.
const generatedFileName = "zz_otelwrap_gen.go"

const generatedPreamble = `// Code generated by otelwrapgen; DO NOT EDIT.`

type config struct {
	moduleDir string
	write     bool
	check     bool
	verbose   bool
}

func main() {
	var cfg config
	flag.StringVar(&cfg.moduleDir, "module", ".", "Go module directory (backend)")
	flag.BoolVar(&cfg.write, "write", true, "write generated files")
	flag.BoolVar(&cfg.check, "check", false, "fail if generated files are missing or stale")
	flag.BoolVar(&cfg.verbose, "v", false, "verbose")
	flag.Parse()

	if err := run(cfg); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

func run(cfg config) error {
	moduleDir, err := filepath.Abs(cfg.moduleDir)
	if err != nil {
		return err
	}

	pkgs, err := loadPackages(moduleDir)
	if err != nil {
		return err
	}

	var generated int
	for _, pkg := range pkgs {
		out, err := generateForPackage(pkg)
		if err != nil {
			return err
		}
		if out == nil {
			continue
		}

		formatted, err := format.Source(out)
		if err != nil {
			return fmt.Errorf("format %s: %w", pkg.PkgPath, err)
		}

		filePath := filepath.Join(pkg.Dir, generatedFileName)
		if err := writeOrCheckGeneratedFile(filePath, formatted, cfg); err != nil {
			return err
		}
		generated++
		if cfg.verbose {
			fmt.Printf("generated %s\n", filePath)
		}
	}

	if cfg.verbose {
		fmt.Printf("done (%d packages)\n", generated)
	}
	return nil
}

func writeOrCheckGeneratedFile(filePath string, generated []byte, cfg config) error {
	if cfg.check {
		current, err := os.ReadFile(filePath)
		if err != nil {
			if os.IsNotExist(err) {
				return fmt.Errorf("generated file %s is missing; run 'go run ./cmd/otelwrapgen'", filePath)
			}
			return fmt.Errorf("read generated file %s: %w", filePath, err)
		}
		if !bytes.Equal(current, generated) {
			return fmt.Errorf("generated file %s is stale; run 'go run ./cmd/otelwrapgen'", filePath)
		}
		return nil
	}

	if !cfg.write {
		return nil
	}
	if err := os.WriteFile(filePath, generated, 0o644); err != nil {
		return fmt.Errorf("write %s: %w", filePath, err)
	}
	return nil
}

func loadPackages(moduleDir string) ([]*packages.Package, error) {
	// We only target two areas:
	// - internal/biz/... (Service interfaces)
	// - internal/store/.../repository (Repository interfaces)
	patterns := []string{
		"./internal/biz/...",
		"./internal/store/.../repository",
	}

	cfg := &packages.Config{
		Mode: packages.NeedName |
			packages.NeedFiles |
			packages.NeedCompiledGoFiles |
			packages.NeedTypes |
			packages.NeedTypesInfo |
			packages.NeedSyntax |
			packages.NeedModule,
		Dir: moduleDir,
	}

	pkgs, err := packages.Load(cfg, patterns...)
	if err != nil {
		return nil, err
	}

	// Filter out packages without go files (edge cases)
	out := make([]*packages.Package, 0, len(pkgs))
	for _, pkg := range pkgs {
		if pkg == nil || pkg.Types == nil || pkg.TypesInfo == nil {
			continue
		}
		if len(pkg.CompiledGoFiles) == 0 {
			continue
		}
		out = append(out, pkg)
	}
	return out, nil
}

func generateForPackage(pkg *packages.Package) ([]byte, error) {
	w := newWriter(pkg)

	interfaces := w.findTargetInterfaces()
	if len(interfaces) == 0 {
		return nil, nil
	}

	w.p(generatedPreamble)
	w.p("package %s", pkg.Name)
	w.p("")

	for _, iface := range interfaces {
		w.addWrapperForInterface(iface)
		w.p("")
	}

	// Insert the import block after all code is generated so we don't miss imports
	// discovered during types.TypeString rendering.
	w.gen.emitImports()

	return w.buf.Bytes(), nil
}

type ifaceInfo struct {
	name string
	obj  any
}

type writer struct {
	pkg *packages.Package
	buf bytes.Buffer

	imports map[string]string
	used    map[string]bool

	gen *generator
}

func newWriter(pkg *packages.Package) *writer {
	w := &writer{
		pkg:     pkg,
		imports: map[string]string{},
		used:    map[string]bool{},
	}
	w.gen = newGenerator(pkg, w)
	return w
}

func (w *writer) p(format string, args ...any) {
	if len(args) == 0 {
		w.buf.WriteString(format)
		w.buf.WriteByte('\n')
		return
	}
	fmt.Fprintf(&w.buf, format, args...)
	w.buf.WriteByte('\n')
}

func (w *writer) findTargetInterfaces() []ifaceInfo {
	return w.gen.findTargetInterfaces()
}

func (w *writer) addWrapperForInterface(iface ifaceInfo) {
	w.gen.addWrapperForInterface(iface)
}

func normalizeIdent(value string) string {
	value = strings.TrimSpace(value)
	if value == "" {
		return "_"
	}
	return value
}
